RTringSignalClaw2Clamp(CLK := g_biDualStation1Chuck2ClampExternalSignal);
RTringSignalClaw3Clamp(CLK := g_biDualStation2Chuck1ClampExternalSignal);
RTringSignalClaw4Clamp(CLK := g_biDualStation2Chuck2ClampExternalSignal);
RTringSignalClaw1Lossen(CLK := g_biDualStation1Chuck1LossenExternalSignal);
RTringSignalClaw2Lossen(CLK := g_biDualStation1Chuck2LossenExternalSignal);
RTringSignalClaw3Lossen(CLK := g_biDualStation2Chuck1LossenExternalSignal);
RTringSignalClaw4Lossen(CLK := g_biDualStation2Chuck2LossenExternalSignal);
IF RTriggerSignalClaw1Control.Q THEN
    IF g_bDualStation1Chuck1Status THEN
		bClaw1Enable := FALSE;
       bClaw1Off := TRUE;
    ELSE
      bClaw1Off := FALSE;
      bClaw1Enable := TRUE;
    END_IF;
END_IF;
IF RTriggerSignalClaw2Control.Q THEN
    IF g_bDualStation1Chuck2Status THEN
      bClaw2Off := TRUE;
      bClaw2Enable := FALSE;
    ELSE
      bClaw2Enable := TRUE;
      bClaw2Off := FALSE;
    END_IF;
END_IF;


IF RTriggerSignalClaw3Control.Q THEN
    IF g_bDualStation2Chuck1Status THEN
		bClaw3Enable := FALSE;
       bClaw3Off := TRUE;
    ELSE
      bClaw3Off := FALSE;
      bClaw3Enable := TRUE;
    END_IF;
END_IF;
IF RTriggerSignalClaw4Control.Q THEN
    IF g_bDualStation2Chuck2Status THEN
      bClaw4Off := TRUE;
      bClaw4Enable := FALSE;
    ELSE
      bClaw4Enable := TRUE;
      bClaw4Off := FALSE;
    END_IF;
END_IF;


