RTriggerDualStation1ChuckOneKeyClamp(CLK := g_bDualStation1AllChuckEnable);
RTriggerDualStation1ChuckOneKeyLossen(CLK := g_bDualStation1AllChuckOff);
IF RTriggerDualStation1ChuckOneKeyClamp.Q THEN
  g_bDualStation1AllChuckEnable := FALSE;
  nDualStation1ChuckState := 10;
  IF (NOT g_bDualAxis1Config) AND (NOT g_bDualAxis2Config) THEN
    nDualStation1ChuckState := 0;
    M.ENABLE[338] := 0;
    g_bFinishedM338_100 := FALSE;
  END_IF;

END_IF;
IF RTriggerDualStation1ChuckOneKeyLossen.Q THEN
  g_bDualStation1AllChuckOff := FALSE;
  nDualStation1ChuckState := 100;
  IF (NOT g_bDualAxis1Config) AND (NOT g_bDualAxis2Config) THEN
    nDualStation1ChuckState := 0;
    M.ENABLE[338] := 0;
    g_bFinishedM338_100 := FALSE;
  END_IF;
END_IF;

RTriggerDualStation1Chuck1Clamp(CLK := g_bDualStation1Claw1Enable);
RTriggerDualStation1Chuck1Lossen(CLK := g_bDualStation1Claw1Off);
IF RTriggerDualStation1Chuck1Clamp.Q THEN
  g_bDualStation1Claw1Enable := FALSE;
  nDualStation1ChuckState := 20;
  IF (NOT g_bDualAxis1Config)  THEN
    nDualStation1ChuckState := 0;
    M.ENABLE[338] := 0;
    g_bFinishedM338_1 := FALSE;
  END_IF;
END_IF;

IF RTriggerDualStation1Chuck1Lossen.Q THEN
  g_bDualStation1Claw1Off := FALSE;
