  END_IF;
END_IF;

IF RTriggerDualStation1Chuck2Lossen.Q THEN
  g_bDualStation1Claw2Off := FALSE;
  nDualStation1ChuckState := 50;
  IF (NOT g_bDualAxis2Config)  THEN
    nDualStation1ChuckState := 0;
    M.ENABLE[338] := 0;
    g_bFinishedM338_1 := FALSE;
  END_IF;
END_IF;



CASE nDualStation1ChuckState OF
  0:
	nDualStation1ChuckState := 0;
  10:(*夹紧*)
	IF g_bDualAxis1Config THEN
		bClaw1Enable := TRUE;
        bClaw1Off := FALSE;
        g_bDualStation1Claw1Off := FALSE;
	END_IF;
	IF g_bDualAxis2Config THEN
      bClaw2Enable := TRUE;
      bClaw2Off := FALSE;
      g_bDualStation2Claw1Off := FALSE;
    END_IF;
    nDualStation1ChuckState :=15;
  15:
	IF g_bDualAxis1Config AND g_bDualAxis2Config THEN
		IF g_bDualStation1Chuck1Status AND  g_bDualStation1Chuck2Status THEN
          nDualStation1ChuckState := 200;
        END_IF;
    ELSIF g_bDualAxis1Config THEN
      IF g_bDualStation1Chuck1Status THEN
          nDualStation1ChuckState := 200;
        END_IF;

    ELSIF g_bDualAxis2Config THEN
		IF  g_bDualStation1Chuck2Status THEN
          nDualStation1ChuckState := 200;
        END_IF;
    END_IF;
  20:(*单卡夹紧*)
		bClaw1Enable := TRUE;
        bClaw1Off := FALSE;
        g_bDualStation1Claw1Off := FALSE;
		nDualStation1ChuckState := 25;
  25:
	IF g_bDualStation1Chuck1Status THEN
         M.ENABLE[338] := 0;
		nDualStation1ChuckState := 0;
		g_bFinishedM338_1 := FALSE;
    END_IF;
  30:(*单卡松开*)
		bClaw1Enable := FALSE;
        bClaw1Off := TRUE;
        g_bDualStation1Claw1Enable := FALSE;
		nDualStation1ChuckState := 35;
  35:
	IF NOT g_bDualStation1Chuck1Status THEN
         M.ENABLE[338] := 0;
		nDualStation1ChuckState := 0;
		g_bFinishedM338_1 := FALSE;
    END_IF;
  40:(*单卡夹紧*)
		bClaw2Enable := TRUE;
        bClaw2Off := FALSE;
        g_bDualStation1Claw2Off := FALSE;
		nDualStation1ChuckState := 45;
  45:
	IF g_bDualStation1Chuck2Status THEN
         M.ENABLE[338] := 0;
		nDualStation1ChuckState := 0;
		g_bFinishedM338_1 := FALSE;
    END_IF;
  50:(*单卡松开*)
		bClaw2Enable := FALSE;
        bClaw2Off := TRUE;
        g_bDualStation1Claw2Enable := FALSE;
		nDualStation1ChuckState := 55;
  55:
	IF NOT g_bDualStation1Chuck2Status THEN
         M.ENABLE[338] := 0;
		nDualStation1ChuckState := 0;
		g_bFinishedM338_1 := FALSE;
    END_IF;
  100:(*松开*)
	IF g_bDualAxis1Config THEN
		bClaw1Enable := FALSE;
        bClaw1Off := TRUE;
        g_bDualStation1Claw1Enable := FALSE;
	END_IF;
	IF g_bDualAxis2Config THEN
      bClaw2Enable := FALSE;
      bClaw2Off := TRUE;
      g_bDualStation2Claw1Enable := FALSE;
    END_IF;
    nDualStation1ChuckState :=150;
  150:
	IF  g_bDualAxis1Config AND  g_bDualAxis2Config THEN
		IF NOT g_bDualStation1Chuck1Status AND NOT g_bDualStation1Chuck2Status THEN
          nDualStation1ChuckState := 200;
        END_IF;
    ELSIF g_bDualAxis1Config THEN
      IF NOT g_bDualStation1Chuck1Status THEN
          nDualStation1ChuckState := 200;
        END_IF;

    ELSIF g_bDualAxis2Config THEN
		IF NOT g_bDualStation1Chuck2Status THEN
          nDualStation1ChuckState := 200;
        END_IF;
    END_IF;

  200:
	M.ENABLE[338] := 0;
    nDualStation1ChuckState := 0;
	g_bFinishedM338_100 := FALSE;

END_CASE;

