  100:(*松开*)
	IF g_bDualAxis3Config THEN
		bClaw3Enable := FALSE;
        bClaw3Off := TRUE;
        g_bDualStation2Claw1Enable := FALSE;
	END_IF;
	IF g_bDualAxis4Config THEN
      bClaw4Enable := FALSE;
      bClaw4Off := TRUE;
      g_bDualStation2Claw2Enable := FALSE;
    END_IF;
    nDualStation2ChuckState :=150;
  150:
