IF bClaw1Enable THEN
  g_boDualStation1Chuck1ClampOutPut := TRUE;
  g_boDualStation1Chuck1LossenOutPut := FALSE;

END_IF;

IF bClaw1Off THEN
  g_boDualStation1Chuck1ClampOutPut := FALSE;
  g_boDualStation1Chuck1LossenOutPut := TRUE;
END_IF;


DualChuck1Control(
	ClampEnable :=bClaw1Enable,(*夹紧*)
    LossenEnable := bClaw1Off ,(*松开*)
    KeepPressure := bDualStation1Chuck1UseKeepPressure,(*保压*)
    KeepPressureTime := nDualStation1Chuck1UseKeepPressureTime,(*保压时间*)
    ClampInplaceDelay := nDualStation1Chuck1ClampDoneTime,(*夹紧完成时间*)
    LossenInplaceDelay := nDualStation1Chuck1LossenDoneTime,(*松开完成时间*)
    UseClampPlaceSignal :=bDualStation1Chuck1UseClampSignal AND ListenBoardInputConfig[550],(*是否使用夹紧到位信号*)
    UseLossenPlaceSignal :=bDualStation1Chuck1UseLossenSignal AND ListenBoardInputConfig[551],(*是否使用松开到位信号*)
    ClampInPlaceSignal := g_bDualStation1Chuck1ClampInPlace,(*夹紧到位*)
    LossenInPlaceSignal := g_bDualStation1Chuck1LossenInPlace,(*松开到位*)
    ChuckStatus := g_bDualStation1Chuck1Status,(*卡盘状态*)
    ChuckDoneWaitTime := nDualStation1Chuck1WaitDoneTime,
    ClampDone => g_bDualStation1Chuck1ClampDone,(*夹紧完成*)
    LossenDone => g_bDualStation1Chuck1LossenDone,(*松开完成*)
    ClawKeepPressureDone => g_bDualStation1Chuck1KeepPressureDone,
    WaitClampDoneOutTimeAlarm => bDualStation1Chuck1ClampWaitNoSignalAlarm,
    WaitLossenDoneOutTimeAlarm => bDualStation1Chuck1LossenWaitNoSignalAlarm

);
IF bDualStation1Chuck1UseKeepPressure AND NOT g_bDualStation1Chuck1KeepPressureDone THEN
  g_boDualStation1Chuck1ClampOutPut := FALSE;
  g_boDualStation1Chuck1LossenOutPut := FALSE;

END_IF;

    (*触发条件只保留一个周期*)
	IF bClaw1Enable  THEN
